/**
 * Regenerates src/modules/design/data/index.ts from the design files in that folder (catalogue
 * Part F). Run by the authoring kit; never edit the generated file by hand.
 */
import fs from 'node:fs';
import path from 'node:path';

const DIR = 'src/modules/design/data';
const files = fs
  .readdirSync(DIR)
  .filter((f) => f.endsWith('.json'))
  .sort();
const ids = files.map((f) => JSON.parse(fs.readFileSync(path.join(DIR, f), 'utf8')).id);
for (const [i, f] of files.entries())
  if (`${ids[i]}.json` !== f)
    throw new Error(`${f}: the file name must be the design id (${ids[i]}.json)`);
const lines = [
  '// Generated by scripts/design-index.mjs from the design files in this folder — do not edit.',
  ...files.map((f, i) => `import d${i} from './${f}' with { type: 'json' };`),
  '',
  '/** Design files (validated by the authoring kit and design-data.test.ts). */',
  `export const DATA_DESIGN_FILES: unknown[] = [${files.map((_, i) => `d${i}`).join(', ')}];`,
  `export const DATA_DESIGN_IDS = [${ids.map((id) => `'${id}'`).join(', ')}] as const;`,
  '',
];
fs.writeFileSync(path.join(DIR, 'index.ts'), lines.join('\n'));
console.log(
  `design index: ${ids.length} design file(s)${ids.length ? ` (${ids.join(', ')})` : ''}`,
);
